package org.eclipse.rdf4j.workbench.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Map;
import java.util.stream.Stream;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.BlankNodeReferences;
import org.eclipse.rdf4j.query.impl.RepositoryBNode;
import org.eclipse.rdf4j.workbench.exceptions.BadRequestException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.mock.web.MockHttpServletRequest;

class ValueDecoderBlankNodeReferenceTest {

	private final ValueFactory factory = SimpleValueFactory.getInstance();
	private final ValueDecoder decoder = new ValueDecoder(null, factory);

	static Stream<String> identifiers() {
		return Stream.of("node", "", "_:already-prefixed", "space > slash\\quote\"", "a%20b+c", "雪😀", "\\u0041");
	}

	@ParameterizedTest
	@MethodSource("identifiers")
	void fixedReferencesPreserveTheCompleteDecodedId(String id) throws Exception {
		assertThat(decoder.decodeValue(BlankNodeReferences.toReference(id))).isEqualTo(factory.createBNode(id));
	}

	@Test
	void decodesEscapedPrefixOnceAndRetainsLegacyBlankNodeForm() throws Exception {
		assertThat(decoder.decodeValue("<\\u005F\\u003Anode>")).isEqualTo(factory.createBNode("node"));
		assertThat(decoder.decodeValue("_:node")).isEqualTo(factory.createBNode("node"));
		assertThat(decoder.decodeValue("<urn:test:\\u003C_:node\\u003E>"))
				.isEqualTo(factory.createIRI("urn:test:<_:node>"));
		assertThat(decoder.decodeValue("\"<_:node>\""))
				.isEqualTo(factory.createLiteral("<_:node>"));
	}

	@ParameterizedTest
	@ValueSource(strings = { "<<(", "<<" })
	void nestedTripleTermsPreserveReferencesAndLiteralContents(String opening) throws Exception {
		String closing = opening.equals("<<(") ? ")>>" : ">>";
		String reference = BlankNodeReferences.toReference("_:subject >\\雪");
		String value = opening + " " + reference + " <urn:test:p> " + opening
				+ " <_:object> <urn:test:p> \"escaped \\\" <_:literal> >>\" " + closing + " " + closing;
		TripleTerm nested = factory.createTripleTerm(factory.createBNode("object"), factory.createIRI("urn:test:p"),
				factory.createLiteral("escaped \" <_:literal> >>"));
		assertThat(decoder.decodeValue(value)).isEqualTo(
				factory.createTripleTerm(factory.createBNode("_:subject >\\雪"), factory.createIRI("urn:test:p"),
						nested));
	}

	@ParameterizedTest
	@ValueSource(strings = { "<_:bad space>", "<_:bad>tail>", "<_:bad\\n>", "<_:bad\\uD800>",
			"<_:bad\\U00110000>", "\"literal\"^^<_:datatype>", "<<( <_:s> <_:predicate> <_:o> )>>",
			"<<( <_:s> <urn:p> \"literal\"^^<_:datatype> )>>", "<<( <_:s> <urn:p> <_:o> )>> trailing" })
	void rejectsMalformedReferencesAndIriOnlyPositions(String value) {
		assertThatThrownBy(() -> decoder.decodeValue(value)).isInstanceOf(BadRequestException.class);
	}

	@Test
	void requestResourceAndValueFieldsAcceptReferencesButIriFieldsRejectThem() throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/explore");
		request.addParameter("resource", "<_:same>");
		request.addParameter("context", "<_:same>");
		request.addParameter("predicate", "<_:same>");
		WorkbenchRequest wrapped = new WorkbenchRequest(null, request, Map.of());
		assertThat(wrapped.getResource("resource")).isInstanceOf(BNode.class).isEqualTo(factory.createBNode("same"));
		assertThat(wrapped.getValue("context")).isEqualTo(factory.createBNode("same"));
		assertThatThrownBy(() -> wrapped.getURI("predicate")).isInstanceOf(BadRequestException.class);
	}

	@Test
	void encodedNestedTermsRoundTripWithoutRenamingBlankNodesOrLiteralContents() throws Exception {
		TripleTerm nested = factory.createTripleTerm(factory.createBNode(""), factory.createIRI("urn:test:p"),
				factory.createLiteral("literal <_:id> \" >>\n\b"));
		TripleTerm value = factory.createTripleTerm(factory.createBNode("_:space >\\雪"),
				factory.createIRI("urn:test:p"), nested);
		assertThat(WorkbenchValueEncoder.encode(value)).contains("<_:_:space\\u0020\\u003E\\u005C雪>", "<_:>");
		assertThat(decoder.decodeValue(WorkbenchValueEncoder.encode(value))).isEqualTo(value);
	}

	@Test
	void negotiatedReferenceOperandsUseRawIdsWhileTransientResultsHaveNoOperand() throws Exception {
		String raw = "space >\\雪";
		var stored = RepositoryBNode.fromNegotiatedResult("rdf4jbo1_s_encoded", raw, true);
		assertThat(WorkbenchValueEncoder.encode(stored)).isEqualTo(BlankNodeReferences.toReference(raw));
		assertThat(decoder.decodeValue(WorkbenchValueEncoder.encode(stored))).isEqualTo(factory.createBNode(raw));
		var transientResult = RepositoryBNode.fromNegotiatedResult("rdf4jbo1_u_encoded", raw, false);
		assertThatThrownBy(() -> WorkbenchValueEncoder.encode(transientResult))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("no reusable");
	}
}
